def main():
    vocabulary=json.loads(VOCAB_PATH.read_text(encoding='utf-8')); phrase=json.loads(PHRASE_PATH.read_text(encoding='utf-8')); translations=phrase.setdefault('translations',{}); rows=[x for x in vocabulary if int(x.get('level',0))==3][1350:1500]; expected={str(x['word']).casefold() for x in rows}; assert set(EN)==expected and set(JA)==expected
    changed=0
    for item in rows:
        word=str(item['word']).casefold(); item['example']=EN[word]; ex=translations.setdefault(f"builtin:{item['id']}",{}).setdefault('example',{})
        for lang,value in [('en',EN[word]),('ja',JA[word])]:
            if ex.get(lang)!=value: ex[lang]=value; changed+=1
    VOCAB_PATH.write_text(json.dumps(vocabulary,ensure_ascii=False,indent=1)+'\n',encoding='utf-8'); PHRASE_PATH.write_text(json.dumps(phrase,ensure_ascii=False,indent=1)+'\n',encoding='utf-8'); print(f'reviewed 700+ English/Japanese examples batch 3d: {len(rows)} terms, {changed} fields')
if __name__=='__main__': main()
